<script setup lang="ts">
import { computed,nextTick,onMounted,onUnmounted,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { ElMessage,ElMessageBox } from 'element-plus';
import { Folder,Document,StarFilled,UploadFilled,Plus,Grid,List,Refresh,Search,ArrowLeft,ArrowRight,MoreFilled } from '@element-plus/icons-vue';
import Uppy from '@uppy/core';
import XHRUpload from '@uppy/xhr-upload';
import { request,download,bytes,uploadUrl,type FileEntry,type Listing } from '../api';
import { desktop,platformSession,leaveGuard,setPending } from '../desktop';
import { dialogs } from '../dialogs';
const route=useRoute(),router=useRouter();
const history=ref([route.path]),historyIndex=ref(0);function travel(delta:number){const target=historyIndex.value+delta;if(target<0||target>=history.value.length)return;historyIndex.value=target;void router.push(history.value[target]);}
const contextMenu=ref<{x:number;y:number;item?:FileEntry}|null>(null),menuElement=ref<HTMLElement>();
const contextActions=computed(()=>{const item=contextMenu.value?.item;if(!item)return view.value==='files'?[{id:'new',label:'新建文件夹'},{id:'upload',label:'上传文件'},{id:'refresh',label:'刷新'}]:[{id:'refresh',label:'刷新'}];if(view.value==='trash')return[{id:'restore',label:'恢复'},{id:'permanent',label:'永久删除'}];return[{id:'open',label:item.kind==='folder'?'打开文件夹':officeFile(item)?'在 Office One 中打开':'预览'},...(item.kind==='file'?[{id:'download',label:'下载'}]:[]),{id:'favorite',label:item.favorite?'取消收藏':'收藏'},...(!item.protected?[{id:'rename',label:'重命名'},{id:'move',label:'移动'},{id:'delete',label:'移到回收站'}]:[])];});
async function showContext(event:MouseEvent|KeyboardEvent,item?:FileEntry){event.preventDefault();event.stopPropagation();selected.value=item;const bounds=(event.currentTarget as HTMLElement).getBoundingClientRect();contextMenu.value={x:'clientX'in event?event.clientX:bounds.left+12,y:'clientY'in event?event.clientY:bounds.top+32,item};await nextTick();const menu=menuElement.value;if(menu&&contextMenu.value){contextMenu.value.x=Math.max(8,Math.min(contextMenu.value.x,innerWidth-menu.offsetWidth-8));contextMenu.value.y=Math.max(8,Math.min(contextMenu.value.y,innerHeight-menu.offsetHeight-8));menu.querySelector<HTMLButtonElement>('button')?.focus();}}
async function contextAction(id:string){contextMenu.value=null;if(id==='new')await edit('new');else if(id==='upload')fileInput.value?.click();else if(id==='refresh')await load();else await operate(id);}
function outsideMenu(event:PointerEvent){if(menuElement.value&&!menuElement.value.contains(event.target as Node))contextMenu.value=null;}function escapeMenu(event:KeyboardEvent){if(event.key==='Escape')contextMenu.value=null;}
const view=computed(()=>route.path==='/trash'?'trash':route.path==='/recent'?'recent':route.path==='/favorites'?'favorites':'files');
const data=ref<Listing>(),loading=ref(false),error=ref(''),search=ref(''),sort=ref('name'),direction=ref('asc'),page=ref(1),display=ref('grid'),viewAccount=ref(''),selected=ref<FileEntry>(),fileInput=ref<HTMLInputElement>();
const uploads=ref<{id:string;name:string;percentage:number;error?:string;complete:boolean}[]>([]),uploading=ref(false);
const uppy=new Uppy({locale:{pluralize:()=>0,strings:{exceedsSize:'%{file} 超过单文件上限 %{size}',noDuplicates:'上传队列中已有 %{fileName}，请移除旧任务后重试',failedToUpload:'%{file} 上传失败',noInternetConnection:'网络已断开',connectedToInternet:'网络已恢复',noMoreFilesAllowed:'无法继续添加文件'}},autoProceed:true,restrictions:{maxFileSize:50*1024**2},onBeforeFileAdded:file=>{if(!data.value||loading.value||view.value!=='files'){ElMessage.warning('请先选择文件夹');return false;}return {...file,meta:{...file.meta,parentId:data.value.parentId}};}});
uppy.use(XHRUpload,{endpoint:file=>{const entry=Array.isArray(file)?file[0]:file;return uploadUrl(`/uploads?parentId=${encodeURIComponent(String(entry.meta.parentId))}&name=${encodeURIComponent(entry.name||'未命名文件')}`);},formData:false,withCredentials:true,limit:2,timeout:120000,shouldRetry:()=>false,onBeforeRequest:async xhr=>{xhr.setRequestHeader('X-CSRF-Token',await platformSession.csrf());},getResponseData:async xhr=>{let body;try{body=JSON.parse(xhr.responseText);}catch{throw new Error('上传服务返回异常');}if(xhr.status>=400)throw new Error(body.message||'上传失败');return body;}});
function syncUploads(){uploads.value=uppy.getFiles().map(f=>({id:f.id,name:f.name||'未命名文件',percentage:Math.round(f.progress.percentage||0),error:f.error||undefined,complete:!!f.progress.uploadComplete}));uploading.value=uppy.getFiles().some(f=>!!f.progress.uploadStarted&&!f.progress.uploadComplete&&!f.error);setPending('upload',uploading.value);}
uppy.on('state-update',syncUploads);uppy.on('restriction-failed',(_file,e)=>ElMessage.error(e.message));uppy.on('upload-success',()=>{void load();});uppy.on('upload-error',(_file,e)=>{ElMessage.error(e.message);});
const clearGuard=leaveGuard(()=>!uploading.value);
let intentHandled='',controller:AbortController|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined,openedId='';
async function load(background:unknown=false){const quiet=background===true;controller?.abort();const current=new AbortController();controller=current;if(!quiet)loading.value=true;error.value='';try{const query=new URLSearchParams({view:view.value,parentId:route.path==='/my-files/desktop'?'desktop':String(route.params.folderId||''),search:search.value,sort:sort.value,direction:direction.value,page:String(page.value),pageSize:'100'});const result=await request<Listing>(`/entries?${query}`,{signal:current.signal});if(current.signal.aborted)return;data.value=result;if(!quiet)selected.value=undefined;uppy.setOptions({restrictions:{maxFileSize:result.quota.maxFile}});}catch(e){if(!current.signal.aborted)error.value=(e as Error).message;}finally{if(!current.signal.aborted)loading.value=false;}}
const officeGranted=ref(false);
onMounted(async()=>{try{const res=await fetch(`${desktop.origin}/api/session`,{credentials:'include',cache:'no-store',signal:AbortSignal.timeout(15000)});if(res.ok){const session=await res.json();viewAccount.value=String(session.user?.id||'');try{display.value=viewAccount.value&&localStorage.getItem(`files:view:${encodeURIComponent(viewAccount.value)}`)==='list'?'list':'grid'}catch{}officeGranted.value=session.apps?.some((app:{id:string})=>app.id==='office-one')===true}}catch{}});
function officeFile(item:FileEntry){return officeGranted.value&&item.kind==='file'&&/\.(docx?|xlsx?|pptx?)$/i.test(item.name)}
async function open(item:FileEntry){if(view.value==='trash')return;if(item.kind==='folder'){await router.push(`/my-files/${item.id}`);return;}if(officeFile(item)){const path=`/documents/${item.id}`;if(desktop.enabled)desktop.openApplication('office-one',path);else location.assign(`${desktop.origin}/auth/start?app=office-one&path=${encodeURIComponent(path)}&display=standalone`);return;}await dialogs.open('file-preview',{id:item.id});await load();}
async function edit(mode:'new'|'rename'|'move'){if(!data.value)return;const result=await dialogs.open(mode==='move'?'file-move':'file-name',mode==='new'?{parentId:data.value.parentId}:{id:selected.value?.id});if(result.outcome==='completed')await load();}
async function operate(command:string){const item=selected.value;if(!item)return;if(command==='open')await open(item);else if(command==='download')await save(item);else if(command==='favorite')await favorite(item);else if(command==='rename'||command==='move')await edit(command==='rename'?'rename':'move');else if(command==='delete'||command==='permanent')await remove(command==='permanent');else if(command==='restore')await action(()=>request('/entries/'+item.id+'/restore',{method:'POST',body:JSON.stringify({version:item.version})}));}
async function favorite(item:FileEntry){await action(()=>request(`/entries/${item.id}`,{method:'PATCH',body:JSON.stringify({favorite:!item.favorite,version:item.version})}));}
async function action(operation:()=>Promise<unknown>){try{await operation();await load();}catch(e){ElMessage.error((e as Error).message);}}
async function remove(permanent=false){const item=selected.value;if(!item)return;try{await ElMessageBox.confirm(permanent?`永久删除「${item.name}」后无法恢复。`:`将「${item.name}」及其内容移到回收站？` ,permanent?'永久删除':'移到回收站',{confirmButtonText:permanent?'永久删除':'移到回收站',cancelButtonText:'取消',type:'warning'});}catch{return;}await action(()=>request(`/entries/${item.id}${permanent?'/permanent':''}`,{method:'DELETE',body:JSON.stringify({version:item.version})}));}
async function save(item:FileEntry){try{await download(item);}catch(e){ElMessage.error((e as Error).message);}}
function addFiles(files:FileList|null){for(const file of Array.from(files||[])){try{uppy.addFile({name:file.name,type:file.type,data:file});}catch(e){ElMessage.error((e as Error).message);}}if(fileInput.value)fileInput.value.value='';}
function drop(event:DragEvent){if(view.value==='files')addFiles(event.dataTransfer?.files||null);}
async function processIntent(){
 const intent=String(route.query.intent||'');if(!['new-folder','rename','move'].includes(intent)||intentHandled===route.fullPath)return;
 intentHandled=route.fullPath;
 try{await nextTick();await load();if(!data.value)return;
 if(intent==='new-folder'){if(route.path!=='/my-files/desktop'||data.value.parentId!==data.value.desktopFolderId)return;await edit('new');}
 else{const id=typeof route.query.open==='string'?route.query.open:'';if(!id)return;const entry=await request<FileEntry>(`/entries/${encodeURIComponent(id)}`);if(entry.protected)throw new Error('系统文件夹不可重命名或移动');await dialogs.open(intent==='rename'?'file-name':'file-move',{id:entry.id});await load();}
 await router.replace({query:{}});
 }catch(e){ElMessage.error((e as Error).message);}finally{intentHandled='';}
}
async function openQuery(){if(['rename','move'].includes(String(route.query.intent||'')))return;const id=typeof route.query.open==='string'?route.query.open:'';if(!id||id===openedId)return;openedId=id;try{const item=await request<FileEntry>(`/entries/${encodeURIComponent(id)}`);if(item.kind==='folder'){await router.replace(`/my-files/${item.id}`);}else{await open(item);await router.replace({query:{}});}}catch(e){ElMessage.error((e as Error).message);}finally{openedId='';}}
watch(()=>route.path,()=>{if(history.value[historyIndex.value]!==route.path){history.value=history.value.slice(0,historyIndex.value+1);history.value.push(route.path);historyIndex.value=history.value.length-1;}page.value=1;search.value='';sort.value=view.value==='recent'?'accessedAt':'name';direction.value=view.value==='recent'?'desc':'asc';void load();});
watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;void load();},250);});watch([sort,direction,page],()=>void load());watch(display,value=>{if(viewAccount.value)try{localStorage.setItem(`files:view:${encodeURIComponent(viewAccount.value)}`,value)}catch{}});watch(()=>route.query.open,()=>void openQuery());watch(()=>[route.query.intent,route.query.open],()=>void processIntent());
function refresh(){if(!document.hidden&&!uploading.value)void load(true);}onMounted(()=>{void load();void openQuery();void processIntent();window.addEventListener('focus',refresh);window.addEventListener('pointerdown',outsideMenu);window.addEventListener('keydown',escapeMenu);});onUnmounted(()=>{controller?.abort();clearTimeout(searchTimer);clearGuard();uppy.destroy();setPending('upload',false);window.removeEventListener('focus',refresh);window.removeEventListener('pointerdown',outsideMenu);window.removeEventListener('keydown',escapeMenu);});
</script>
<template><section class="finder" @contextmenu="showContext($event)" @keydown.shift.f10.prevent="showContext($event)" @dragover.prevent @drop.prevent="drop"><input ref="fileInput" type="file" multiple hidden @change="addFiles(($event.target as HTMLInputElement).files)"><header class="finder-toolbar"><div class="finder-history"><el-button text :icon="ArrowLeft" :disabled="historyIndex===0" aria-label="后退" @click="travel(-1)"/><el-button text :icon="ArrowRight" :disabled="historyIndex>=history.length-1" aria-label="前进" @click="travel(1)"/></div><strong class="finder-folder-title">{{view==='files'?(data?.breadcrumbs.at(-1)?.name||'我的文件'):String(route.meta.title)}}</strong><div class="finder-tools"><el-button text :icon="Plus" :disabled="view!=='files'||!data||loading" aria-label="新建文件夹" title="新建文件夹" @click="edit('new')"/><el-button text :icon="UploadFilled" :disabled="view!=='files'||!data||loading" aria-label="上传文件" title="上传文件" @click="fileInput?.click()"/><el-button text :icon="Refresh" :loading="loading" aria-label="刷新" title="刷新" @click="load"/><div class="finder-view-switch" role="group" aria-label="视图"><el-button :type="display==='grid'?'primary':undefined" :aria-pressed="display==='grid'" aria-label="图标视图" @click="display='grid'"><el-icon><Grid/></el-icon></el-button><el-button :type="display==='list'?'primary':undefined" :aria-pressed="display==='list'" aria-label="列表视图" @click="display='list'"><el-icon><List/></el-icon></el-button></div><el-dropdown trigger="click" @command="(value:string)=>{sort=value;direction=value==='name'?'asc':'desc'}"><el-button text aria-label="排序">排序</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="name">按名称</el-dropdown-item><el-dropdown-item command="updatedAt">按修改时间</el-dropdown-item><el-dropdown-item command="size">按大小</el-dropdown-item><el-dropdown-item v-if="view==='recent'" command="accessedAt">按访问时间</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button text class="sort-direction" @click="direction=direction==='asc'?'desc':'asc'">{{direction==='asc'?'↑':'↓'}}</el-button></div><el-input v-model="search" :prefix-icon="Search" placeholder="搜索" clearable aria-label="搜索文件" class="finder-search"/></header><div class="finder-path"><el-breadcrumb v-if="view==='files'&&data"><el-breadcrumb-item v-for="crumb in data.breadcrumbs" :key="crumb.id"><button @click="router.push(crumb.protected==='root'?'/my-files':`/my-files/${crumb.id}`)">{{crumb.name}}</button></el-breadcrumb-item></el-breadcrumb><span v-else>{{view==='trash'?'回收站':view==='recent'?'最近使用':'收藏'}}</span></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><div v-if="route.query.intent==='upload'" class="finder-upload-intent"><span>选择要上传到桌面的文件</span><el-button type="primary" :disabled="loading||!data" @click="fileInput?.click()">选择文件</el-button><el-button text @click="router.replace({query:{}})">取消</el-button></div><div class="finder-selection"><span>{{selected?selected.name:view==='trash'?'永久删除后才会释放空间':'双击打开文件或文件夹；也可以拖入文件上传'}}</span><el-dropdown v-if="selected" trigger="click" @command="operate"><el-button text :icon="MoreFilled" aria-label="文件操作">操作</el-button><template #dropdown><el-dropdown-menu><template v-if="view==='trash'"><el-dropdown-item command="restore">恢复</el-dropdown-item><el-dropdown-item command="permanent">永久删除</el-dropdown-item></template><template v-else><el-dropdown-item command="open">{{selected.kind==='folder'?'打开文件夹':officeFile(selected)?'在 Office One 中打开':'预览'}}</el-dropdown-item><el-dropdown-item v-if="selected.kind==='file'" command="download">下载</el-dropdown-item><el-dropdown-item command="favorite">{{selected.favorite?'取消收藏':'收藏'}}</el-dropdown-item><template v-if="!selected.protected"><el-dropdown-item command="rename" divided>重命名</el-dropdown-item><el-dropdown-item command="move">移动</el-dropdown-item><el-dropdown-item command="delete" divided>移到回收站</el-dropdown-item></template></template></el-dropdown-menu></template></el-dropdown></div><div class="finder-content" aria-label="文件内容" tabindex="0" @click.self="selected=undefined"><table v-if="display==='list'" class="finder-list"><thead><tr><th>名称</th><th>修改日期</th><th>大小</th><th>类型</th></tr></thead><tbody><tr v-for="item in data?.items||[]" :key="item.id" :class="{'is-selected':selected?.id===item.id}" tabindex="0" @contextmenu="showContext($event,item)" @keydown.shift.f10.prevent="showContext($event,item)" @click="selected=item" @dblclick="open(item)" @keydown.enter="open(item)" @keydown.space.prevent="selected=item"><td><div class="file-name"><el-icon :class="item.kind==='folder'?'folder-icon':''"><Folder v-if="item.kind==='folder'"/><Document v-else/></el-icon><span>{{item.name}}</span><el-icon v-if="item.favorite" class="favorite-icon"><StarFilled/></el-icon></div></td><td>{{new Date(item.updatedAt).toLocaleString('zh-CN')}}</td><td>{{item.kind==='folder'?'—':bytes(item.size)}}</td><td>{{item.kind==='folder'?'文件夹':item.name.split('.').length>1?item.name.split('.').at(-1)?.toUpperCase()+' 文件':'文件'}}</td></tr><tr v-if="!data?.items.length"><td colspan="4" class="finder-list-empty">{{loading?'正在加载…':'这里还没有文件'}}</td></tr></tbody></table><div v-else class="file-grid" @click.self="selected=undefined"><button v-for="item in data?.items||[]" :key="item.id" class="file-tile" :class="{'is-selected':selected?.id===item.id}" @contextmenu="showContext($event,item)" @keydown.shift.f10.prevent="showContext($event,item)" @click="selected=item" @dblclick="open(item)" @keydown.enter.prevent="open(item)"><svg v-if="item.kind==='folder'" class="finder-file-art" viewBox="0 0 80 64" aria-hidden="true"><path d="M5 14a5 5 0 0 1 5-5h23l7 7h30a5 5 0 0 1 5 5v34a5 5 0 0 1-5 5H10a5 5 0 0 1-5-5z" fill="#4aa9df"/><path d="M5 24a5 5 0 0 1 5-5h60a5 5 0 0 1 5 5v31a5 5 0 0 1-5 5H10a5 5 0 0 1-5-5z" fill="#72c4f2"/><path d="M10 19h60" stroke="#a5defa" stroke-width="2"/></svg><svg v-else class="finder-file-art document-art" viewBox="0 0 64 76" aria-hidden="true"><path d="M10 3h30l15 16v50a4 4 0 0 1-4 4H10a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4z" fill="#fff" stroke="#c7cdd6" stroke-width="1.5"/><path d="M40 3v16h15" fill="#eef2f7" stroke="#c7cdd6"/><path d="M17 32h25M17 39h25M17 46h18" stroke="#c6d6e9" stroke-width="3"/><text x="31" y="63" text-anchor="middle" font-size="10" font-family="sans-serif" fill="#5784b9">{{item.name.split('.').length>1?item.name.split('.').at(-1)?.slice(0,6).toUpperCase():'FILE'}}</text></svg><span class="file-tile-name">{{item.name}}</span><small>{{item.kind==='folder'?'文件夹':bytes(item.size)}}{{item.favorite?' · ★':''}}</small></button><el-empty v-if="!data?.items.length" :description="loading?'正在加载…':search?'没有匹配的文件':'这里还没有文件'"/></div></div><section v-if="uploads.length" class="finder-uploads"><details :open="uploading||uploads.some(item=>item.error)"><summary>上传任务 · {{uploads.filter(item=>item.complete).length}} / {{uploads.length}} 已完成</summary><div v-for="upload in uploads" :key="upload.id" class="upload-row"><span>{{upload.name}}</span><el-progress :percentage="upload.percentage" :status="upload.error?'exception':upload.complete?'success':undefined"/><span v-if="upload.error" class="upload-error">{{upload.error}}</span><el-button v-if="upload.error" size="small" @click="uppy.retryUpload(upload.id)">重试</el-button><el-button v-if="upload.error||upload.complete" text size="small" @click="uppy.removeFile(upload.id)">移除任务</el-button></div><p>单文件最多 {{bytes(data?.quota.maxFile||50*1024**2)}}，同名文件自动保留两份。</p></details></section><footer class="finder-status"><span>{{data?.total||0}} 个项目{{selected?'，已选择 1 项':''}}</span><el-pagination v-if="(data?.total||0)>100" v-model:current-page="page" :page-size="100" :total="data?.total||0" layout="prev,pager,next"/><span v-if="data">可用 {{bytes(Math.max(0,data.quota.limit-data.quota.used))}}</span></footer></section><Teleport to="body"><div v-if="contextMenu" ref="menuElement" class="finder-context-menu" role="menu" :style="{left:contextMenu.x+'px',top:contextMenu.y+'px'}" @contextmenu.prevent><button v-for="action in contextActions" :key="action.id" role="menuitem" @click="contextAction(action.id)">{{action.label}}</button></div></Teleport></template>













